package popcount

import "math/bits"



// Popcount returns the number of set bits across all words of xs.
func Popcount(xs []uint64) int {
	var ones, twos, fours uint64
	n := 0
	for len(xs) >= 8 {
		a0, a1, a2, a3 := xs[0], xs[1], xs[2], xs[3]
		a4, a5, a6, a7 := xs[4], xs[5], xs[6], xs[7]
		// CSA(ones; a0, a1) -> carry t1
		t1 := (ones & a0) | ((ones ^ a0) & a1)
		ones = ones ^ a0 ^ a1
		// CSA(ones; a2, a3) -> carry t2
		t2 := (ones & a2) | ((ones ^ a2) & a3)
		ones = ones ^ a2 ^ a3
		// CSA(twos; t1, t2) -> carry f1
		f1 := (twos & t1) | ((twos ^ t1) & t2)
		twos = twos ^ t1 ^ t2
		// CSA(ones; a4, a5) -> carry t1
		t1 = (ones & a4) | ((ones ^ a4) & a5)
		ones = ones ^ a4 ^ a5
		// CSA(ones; a6, a7) -> carry t2
		t2 = (ones & a6) | ((ones ^ a6) & a7)
		ones = ones ^ a6 ^ a7
		// CSA(twos; t1, t2) -> carry f2
		f2 := (twos & t1) | ((twos ^ t1) & t2)
		twos = twos ^ t1 ^ t2
		// CSA(fours; f1, f2) -> carry eights
		e := (fours & f1) | ((fours ^ f1) & f2)
		fours = fours ^ f1 ^ f2
		n += 8 * bits.OnesCount64(e)
		xs = xs[8:]
	}
	n += 4*bits.OnesCount64(fours) + 2*bits.OnesCount64(twos) + bits.OnesCount64(ones)
	if len(xs)&4 != 0 {
		n += bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1]) +
			bits.OnesCount64(xs[2]) + bits.OnesCount64(xs[3])
		xs = xs[4:]
	}
	if len(xs)&2 != 0 {
		n += bits.OnesCount64(xs[0]) + bits.OnesCount64(xs[1])
		xs = xs[2:]
	}
	if len(xs) != 0 {
		n += bits.OnesCount64(xs[0])
	}
	return n
}

